values
  ((select id from w), 'recall', 'Fill in the missing word: what region does the text say Damascus threshed with instruments of iron?', 'Amos 1:3', 'For three transgressions of Damascus, yes, for four, I will not turn away its punishment, because they have threshed Gilead with threshing instruments of iron.', 'WEB', 2,
